#include <stddef.h>
#include <stdint.h>
#include <klee/klee.h>

// Declaration from fastfetch
void* memrchr(const void* s, int c, size_t n);

// Include the actual implementation
#include "common/memrchr.h"

// Include the implementation
#include "impl/memrchr.c"

int main() {
    // Create a symbolic buffer
    char buffer[16];
    klee_make_symbolic(buffer, sizeof(buffer), "buffer");

    // Symbolic character to search for
    int c;
    klee_make_symbolic(&c, sizeof(c), "c");

    // Symbolic length n (bounded to buffer size)
    size_t n;
    klee_make_symbolic(&n, sizeof(n), "n");
    klee_assume(n <= 16);

    // Call memrchr
    void* result = memrchr(buffer, c, n);

    // Verify correctness: if result is not NULL, *result should equal c
    if (result != NULL) {
        klee_assert(*(char*)result == (char)c);
        // Result should be within the buffer
        klee_assert(result >= (void*)buffer && result < (void*)(buffer + n));
    } else {
        // If result is NULL, c should not be in the first n bytes of buffer
        for (size_t i = 0; i < n; i++) {
            klee_assume(buffer[i] != (char)c);
        }
    }

    return 0;
}
