cat > /workspace/klee-harnesses/harness_FFlist.c << 'HARNESS_EOF'
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>
#include <klee/klee.h>

// FFlist structure from fastfetch
typedef struct FFlist {
    uint8_t* data;
    uint32_t length;
    uint32_t capacity;
} FFlist;

// Inline functions from FFlist.h reimplemented
static inline void ffListInit(FFlist* list) {
    list->capacity = 0;
    list->length = 0;
    list->data = NULL;
}

static inline void ffListInitA(FFlist* list, uint32_t elementSize, uint32_t capacity) {
    ffListInit(list);
    list->capacity = capacity;
    list->data = (capacity == 0) ? NULL : (uint8_t*) malloc((size_t) capacity * elementSize);
}

static inline void* ffListGet(const FFlist* list, uint32_t elementSize, uint32_t index) {
    return list->data + (index * elementSize);
}

static inline void ffListReserve(FFlist* list, uint32_t elementSize, uint32_t newCapacity) {
    if (newCapacity <= list->capacity) {
        return;
    }
    list->data = (uint8_t*) realloc(list->data, (size_t) newCapacity * elementSize);
    list->capacity = newCapacity;
}

static inline void* ffListAdd(FFlist* list, uint32_t elementSize) {
    if (list->length == list->capacity) {
        ffListReserve(list, elementSize, list->capacity == 0 ? 16 : list->capacity * 2);
    }
    ++list->length;
    return ffListGet(list, elementSize, list->length - 1);
}

static inline void ffListDestroy(FFlist* list) {
    if (!list->data) return;
    list->capacity = list->length = 0;
    free(list->data);
    list->data = NULL;
}

// Functions from FFlist.c
bool ffListShift(FFlist* list, uint32_t elementSize, void* __restrict result) {
    if (list->length == 0) {
        return false;
    }
    memcpy(result, list->data, elementSize);
    memmove(list->data, list->data + elementSize, (size_t) elementSize * (list->length - 1));
    --list->length;
    return true;
}

bool ffListPop(FFlist* list, uint32_t elementSize, void* __restrict result) {
    if (list->length == 0) {
        return false;
    }
    memcpy(result, ffListGet(list, elementSize, list->length - 1), elementSize);
    --list->length;
    return true;
}

int main() {
    FFlist list;
    uint32_t elementSize = sizeof(uint32_t); // 4 bytes

    // Initialize with symbolic capacity
    uint32_t initCapacity;
    klee_make_symbolic(&initCapacity, sizeof(initCapacity), "initCapacity");
    klee_assume(initCapacity > 0 && initCapacity <= 8);

    ffListInitA(&list, elementSize, initCapacity);

    // Add some symbolic elements
    uint32_t numAdd;
    klee_make_symbolic(&numAdd, sizeof(numAdd), "numAdd");
    klee_assume(numAdd <= initCapacity); // Don't exceed initial capacity

    for (uint32_t i = 0; i < numAdd; i++) {
        uint32_t* elem = (uint32_t*) ffListAdd(&list, elementSize);
        *elem = i;
    }

    klee_assert(list.length == numAdd);

    // Test pop operation
    uint32_t popResult;
    bool popOk = ffListPop(&list, elementSize, &popResult);

    if (numAdd > 0) {
        klee_assert(popOk == true);
        klee_assert(list.length == numAdd - 1);
    } else {
        klee_assert(popOk == false);
        klee_assert(list.length == 0);
    }

    // Test shift operation
    uint32_t shiftResult;
    bool shiftOk = ffListShift(&list, elementSize, &shiftResult);

    if (list.length > 0) {
        klee_assert(shiftOk == true);
    } else {
        klee_assert(shiftOk == false);
    }

    ffListDestroy(&list);

    return 0;
}
HARNESS_EOF
echo "FFlist harness created"

