cat > /workspace/klee-harnesses/harness_trim.c << 'HARNESS_EOF'
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <stdlib.h>
#include <klee/klee.h>

// Simplified FFstrbuf from fastfetch
typedef struct FFstrbuf {
    uint32_t allocated;
    uint32_t length;
    char* chars;
} FFstrbuf;

static inline void ffStrbufInitA(FFstrbuf* strbuf, uint32_t allocate) {
    strbuf->allocated = allocate;
    strbuf->length = 0;
    if (allocate > 0) {
        strbuf->chars = (char*) malloc(allocate);
        if (strbuf->chars) {
            strbuf->chars[0] = '\0';
        }
    } else {
        strbuf->chars = NULL;
    }
}

static inline void ffStrbufDestroy(FFstrbuf* strbuf) {
    if (strbuf->allocated > 0) {
        free(strbuf->chars);
    }
    strbuf->allocated = 0;
    strbuf->length = 0;
    strbuf->chars = NULL;
}

// ffStrbufEndsWithC
static inline bool ffStrbufEndsWithC(const FFstrbuf* strbuf, char c) {
    return strbuf->length > 0 && strbuf->chars[strbuf->length - 1] == c;
}

// ffStrbufTrimLeft from FFstrbuf.c
void ffStrbufTrimLeft(FFstrbuf* strbuf, char c) {
    if (strbuf->length == 0) {
        return;
    }
    uint32_t index = 0;
    while (index < strbuf->length && strbuf->chars[index] == c) {
        ++index;
    }
    if (index == 0) {
        return;
    }
    // Only handle dynamic strings
    if (strbuf->allocated == 0) {
        strbuf->length -= index;
        strbuf->chars += index;
        return;
    }
    memmove(strbuf->chars, strbuf->chars + index, strbuf->length - index);
    strbuf->length -= index;
    strbuf->chars[strbuf->length] = '\0';
}

// ffStrbufTrimRight from FFstrbuf.c
void ffStrbufTrimRight(FFstrbuf* strbuf, char c) {
    if (strbuf->length == 0) {
        return;
    }
    if (!ffStrbufEndsWithC(strbuf, c)) {
        return;
    }
    do {
        --strbuf->length;
    } while (ffStrbufEndsWithC(strbuf, c));
    if (strbuf->allocated > 0) {
        strbuf->chars[strbuf->length] = '\0';
    }
}

int main() {
    FFstrbuf strbuf;
    ffStrbufInitA(&strbuf, 16);

    // Fill with symbolic content
    klee_make_symbolic(strbuf.chars, 16, "strbuf_chars");
    strbuf.chars[15] = '\0';

    uint32_t len;
    klee_make_symbolic(&len, sizeof(len), "len");
    klee_assume(len > 0 && len < 16);
    strbuf.length = len;

    char trimChar;
    klee_make_symbolic(&trimChar, sizeof(trimChar), "trimChar");

    // Test ffStrbufTrimLeft
    uint32_t origLen = strbuf.length;
    ffStrbufTrimLeft(&strbuf, trimChar);

    // After trim left: first char should not equal trimChar (or length is 0)
    klee_assert(strbuf.length <= origLen);
    if (strbuf.length > 0) {
        klee_assert(strbuf.chars[0] != trimChar);
    }
    klee_assert(strbuf.chars[strbuf.length] == '\0');

    // Test ffStrbufTrimRight
    origLen = strbuf.length;
    ffStrbufTrimRight(&strbuf, trimChar);

    // After trim right: last char should not equal trimChar (or length is 0)
    klee_assert(strbuf.length <= origLen);
    if (strbuf.length > 0) {
        klee_assert(strbuf.chars[strbuf.length - 1] != trimChar);
    }

    ffStrbufDestroy(&strbuf);

    return 0;
}
HARNESS_EOF
echo "trim harness created"

