#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <stdlib.h>
#include <klee/klee.h>

typedef struct FFstrbuf {
    uint32_t allocated;
    uint32_t length;
    char* chars;
} FFstrbuf;

static inline void ffStrbufInitA(FFstrbuf* strbuf, uint32_t allocate) {
    strbuf->allocated = allocate;
    strbuf->length = 0;
    if (allocate > 0) {
        strbuf->chars = (char*) malloc(allocate);
        if (strbuf->chars) {
            strbuf->chars[0] = '\0';
        }
    } else {
        strbuf->chars = NULL;
    }
}

static inline void ffStrbufDestroy(FFstrbuf* strbuf) {
    if (strbuf->allocated > 0) {
        free(strbuf->chars);
    }
    strbuf->allocated = 0;
    strbuf->length = 0;
    strbuf->chars = NULL;
}

static inline void ffStrbufClear(FFstrbuf* strbuf) {
    if (strbuf->allocated > 0) {
        strbuf->chars[0] = '\0';
    }
    strbuf->length = 0;
}

// ffStrbufSubstrAfter from FFstrbuf.c
bool ffStrbufSubstrAfter(FFstrbuf* strbuf, uint32_t index) {
    if (index >= strbuf->length) {
        ffStrbufClear(strbuf);
        return true;
    }
    if (strbuf->allocated == 0) {
        strbuf->length -= index + 1;
        strbuf->chars += index + 1;
        return true;
    }
    memmove(strbuf->chars, strbuf->chars + index + 1, strbuf->length - index - 1);
    strbuf->length -= (index + 1);
    strbuf->chars[strbuf->length] = '\0';
    return true;
}

int main() {
    FFstrbuf strbuf;
    ffStrbufInitA(&strbuf, 16);

    klee_make_symbolic(strbuf.chars, 16, "strbuf_chars");
    strbuf.chars[15] = '\0';

    uint32_t len;
    klee_make_symbolic(&len, sizeof(len), "len");
    klee_assume(len < 16);
    strbuf.length = len;

    uint32_t index;
    klee_make_symbolic(&index, sizeof(index), "index");
    klee_assume(index < 16);

    uint32_t origLen = strbuf.length;

    bool result = ffStrbufSubstrAfter(&strbuf, index);

    klee_assert(result == true);

    if (index >= origLen) {
        klee_assert(strbuf.length == 0);
    } else {
        klee_assert(strbuf.length == origLen - index - 1);
        klee_assert(strbuf.chars[strbuf.length] == '\0');
    }

    ffStrbufDestroy(&strbuf);
    return 0;
}
HARNESS_EOF
