bool ffStrbufSubstrBefore(FFstrbuf* strbuf, uint32_t index) {
    if (strbuf->length <= index) {
        return false;
    }
    if (strbuf->allocated == 0) {
        return false;
    }
    strbuf->length = index;
    strbuf->chars[strbuf->length] = '\0';
    return true;
}

