    klee_assert(strbuf.length <= origLen);
    if (strbuf.length > 0) {
        klee_assert(strbuf.chars[0] != trimChar);
    }
    klee_assert(strbuf.chars[strbuf.length] == '\0');

    // Test ffStrbufTrimRight
    origLen = strbuf.length;
    ffStrbufTrimRight(&strbuf, trimChar);

    // After trim right: last char should not equal trimChar (or length is 0)
    klee_assert(strbuf.length <= origLen);
    if (strbuf.length > 0) {
        klee_assert(strbuf.chars[strbuf.length - 1] != trimChar);
    }

    ffStrbufDestroy(&strbuf);

    return 0;
}
