#include <stdint.h>
#include <klee/klee.h>

// From fastfetch widechar_width
// Simplified version for KLEE analysis
// Return values: 0 (nonprint), 1 (narrow), 2 (wide)
typedef enum {
    widechar_nonprint = -1,
    widechar_combining = -2,
    widechar_ambiguous = -3,
    widechar_private_use = -4,
    widechar_unassigned = -5,
    widechar_widened_in_9 = -6,
    widechar_non_character = -7,
} widechar_width_t;

// Simplified mk_wcwidth for KLEE
// Tests specific character ranges for width
int mk_wcwidth(uint32_t wc) {
    // Null character
    if (wc == 0) return 0;

    // Control characters
    if (wc < 32 || (wc >= 0x7f && wc < 0xa0)) return 0;  // nonprint

    // ASCII printable
    if (wc < 0x7f) return 1;

    // Latin-1 supplement
    if (wc < 0x100) return 1;

    // CJK and wide chars ranges
    if ((wc >= 0x1100 && wc <= 0x115F) ||  // Hangul Jamo
        (wc >= 0x2E80 && wc <= 0xA4CF) ||  // CJK
        (wc >= 0xAC00 && wc <= 0xD7A3) ||  // Hangul
        (wc >= 0xF900 && wc <= 0xFAFF) ||  // CJK compatibility
        (wc >= 0xFE30 && wc <= 0xFE4F) ||  // CJK compatibility forms
        (wc >= 0xFF00 && wc <= 0xFF60) ||  // Fullwidth forms
        (wc >= 0xFFE0 && wc <= 0xFFE6) ||  // Fullwidth signs
        (wc >= 0x20000 && wc <= 0x2FFFD) ||  // CJK Extension B
        (wc >= 0x30000 && wc <= 0x3FFFD))   // CJK Extension C
    {
        return 2;
    }

    // Default narrow
    return 1;
}

int main() {
    uint32_t wc;
    klee_make_symbolic(&wc, sizeof(wc), "wc");

    int width = mk_wcwidth(wc);

    // Width should be 0, 1, or 2
    klee_assert(width >= 0 && width <= 2);

    // Control characters should have width 0
    if (wc < 32 || (wc >= 0x7f && wc < 0xa0)) {
        klee_assert(width == 0);
    }

    // Null should be 0
    if (wc == 0) {
        klee_assert(width == 0);
    }

    // CJK ranges should be 2
    if ((wc >= 0x1100 && wc <= 0x115F) ||
        (wc >= 0xAC00 && wc <= 0xD7A3)) {
        klee_assert(width == 2);
    }

    // ASCII printable should be 1
    if (wc >= 32 && wc < 0x7f) {
        klee_assert(width == 1);
    }

    return 0;
}
