cat > /workspace/klee-harnesses/harness_strbuf_count.c << 'HARNESS_EOF'
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <stdlib.h>
#include <klee/klee.h>

typedef struct FFstrbuf {
    uint32_t allocated;
    uint32_t length;
    char* chars;
} FFstrbuf;

static inline void ffStrbufInitA(FFstrbuf* strbuf, uint32_t allocate) {
    strbuf->allocated = allocate;
    strbuf->length = 0;
    if (allocate > 0) {
        strbuf->chars = (char*) malloc(allocate);
        if (strbuf->chars) {
            strbuf->chars[0] = '\0';
        }
    } else {
        strbuf->chars = NULL;
    }
}

static inline void ffStrbufDestroy(FFstrbuf* strbuf) {
    if (strbuf->allocated > 0) {
        free(strbuf->chars);
    }
    strbuf->allocated = 0;
    strbuf->length = 0;
    strbuf->chars = NULL;
}

// ffStrbufCountC from FFstrbuf.c
uint32_t ffStrbufCountC(const FFstrbuf* strbuf, char e) {
    uint32_t result = 0;
    for (uint32_t i = 0; i < strbuf->length; i++) {
        if (strbuf->chars[i] == e) {
            result++;
        }
    }
    return result;
}

// ffStrbufSubstrBefore from FFstrbuf.c
bool ffStrbufSubstrBefore(FFstrbuf* strbuf, uint32_t index) {
    if (strbuf->length <= index) {
        return false;
    }
    if (strbuf->allocated == 0) {
        return false;
    }
    strbuf->length = index;
    strbuf->chars[strbuf->length] = '\0';
    return true;
}

int main() {
    FFstrbuf strbuf;
    ffStrbufInitA(&strbuf, 16);

    klee_make_symbolic(strbuf.chars, 16, "strbuf_chars");
    strbuf.chars[15] = '\0';

    uint32_t len;
    klee_make_symbolic(&len, sizeof(len), "len");
    klee_assume(len < 16);
    strbuf.length = len;

    char c;
    klee_make_symbolic(&c, sizeof(c), "c");

    uint32_t count = ffStrbufCountC(&strbuf, c);

    // Verify: count should never exceed length
    klee_assert(count <= strbuf.length);

    // Test ffStrbufSubstrBefore
    uint32_t substrIndex;
    klee_make_symbolic(&substrIndex, sizeof(substrIndex), "substrIndex");
    klee_assume(substrIndex < 16);

    uint32_t oldLength = strbuf.length;
    bool modified = ffStrbufSubstrBefore(&strbuf, substrIndex);

    if (oldLength > substrIndex) {
        klee_assert(modified == true);
        klee_assert(strbuf.length == substrIndex);
        klee_assert(strbuf.chars[strbuf.length] == '\0');
    } else {
        klee_assert(modified == false);
    }

    ffStrbufDestroy(&strbuf);

    return 0;
}
HARNESS_EOF

echo "=== Recompiling strbuf_count ===" && clang-17 -emit-llvm -c -g -O0 -Xclang -disable-O0-optnone \
  -I/workspace/fastfetch/src \
  -I/usr/local/include \
  -include klee/klee.h \
  /workspace/klee-harnesses/harness_strbuf_count.c \
  -o /workspace/klee-bitcode/harness_strbuf_count.bc 2>&1 && echo "Compiled OK""}

