#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <ctype.h>
#include <klee/klee.h>

// From fastfetch strutil.h
static inline bool ffCharIsEnglishAlphabet(char c) {
    return ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z');
}

static inline bool ffCharIsDigit(char c) {
    return '0' <= c && c <= '9';
}

static inline bool ffCharIsHexDigit(char c) {
    return ffCharIsDigit(c) || ('a' <= c && c <= 'f') || ('A' <= c && c <= 'F');
}

static inline int8_t ffHexCharToInt(char c) {
    if (ffCharIsDigit(c)) {
        return (int8_t) (c - '0');
    } else if ('a' <= c && c <= 'f') {
        return (int8_t) (c - 'a' + 10);
    } else if ('A' <= c && c <= 'F') {
        return (int8_t) (c - 'A' + 10);
    } else {
        return -1;
    }
}

static inline bool ffStrEndsWith(const char* str, const char* compareTo) {
    size_t strLength = strlen(str);
    size_t compareToLength = strlen(compareTo);
    if (strLength < compareToLength) {
        return false;
    }
    return memcmp(str + strLength - compareToLength, compareTo, compareToLength) == 0;
}

static inline char* ffStrCopy(char* __restrict__ dst, const char* __restrict__ src, size_t dstBufSiz) {
    if (dst == NULL || dstBufSiz == 0) {
        return dst;
    }
    size_t len = strnlen(src, dstBufSiz - 1);
    memcpy(dst, src, len);
    dst[len] = '\0';
    return dst + len;
}

int main() {
    // Test ffCharIsDigit
    char c;
    klee_make_symbolic(&c, sizeof(c), "c");

    bool isDigit = ffCharIsDigit(c);
    bool isAlpha = ffCharIsEnglishAlphabet(c);
    bool isHex = ffCharIsHexDigit(c);
    int8_t hexVal = ffHexCharToInt(c);

    // Verify consistency
    if (isDigit) {
        klee_assert(hexVal >= 0 && hexVal <= 9);
        klee_assert(isHex == true);
    }

    if (isHex) {
        klee_assert(hexVal >= 0 && hexVal <= 15);
    } else {
        klee_assert(hexVal == -1);
    }

    // If it's a hex digit but not a decimal digit, it must be a-f or A-F
    if (isHex && !isDigit) {
        klee_assert(('a' <= c && c <= 'f') || ('A' <= c && c <= 'F'));
    }

    // ffCharIsEnglishAlphabet should not overlap with digits
    if (isDigit) {
        klee_assert(isAlpha == false);
    }

    // Test ffStrEndsWith with concrete strings
    char str[8];
    klee_make_symbolic(str, sizeof(str), "str");
    str[7] = '\0';

    // Test ffStrCopy
    char dst[8];
    char* ret = ffStrCopy(dst, str, sizeof(dst));
    klee_assert(ret != NULL);
    klee_assert(dst[7] == '\0');
    // dst should be a valid null-terminated copy of str (bounded by buffer size)
    size_t expectedLen = strnlen(str, 7);
    klee_assert(dst[expectedLen] == '\0');

    return 0;
}
