#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <stdlib.h>
#include <klee/klee.h>

typedef struct FFstrbuf {
    uint32_t allocated;
    uint32_t length;
    char* chars;
} FFstrbuf;

static inline void ffStrbufInitA(FFstrbuf* strbuf, uint32_t allocate) {
    strbuf->allocated = allocate;
    strbuf->length = 0;
    if (allocate > 0) {
        strbuf->chars = (char*) malloc(allocate);
        if (strbuf->chars) {
            strbuf->chars[0] = '\0';
        }
    } else {
        strbuf->chars = NULL;
    }
}

static inline void ffStrbufDestroy(FFstrbuf* strbuf) {
    if (strbuf->allocated > 0) {
        free(strbuf->chars);
    }
    strbuf->allocated = 0;
    strbuf->length = 0;
    strbuf->chars = NULL;
}

static inline bool ffStrbufEndsWithC(const FFstrbuf* strbuf, char c) {
    return strbuf->length > 0 && strbuf->chars[strbuf->length - 1] == c;
}

static inline void ffStrbufAppendC(FFstrbuf* strbuf, char c) {
    if (strbuf->allocated == 0) return;
    if (strbuf->length + 1 >= strbuf->allocated) return;
    strbuf->chars[strbuf->length++] = c;
    strbuf->chars[strbuf->length] = '\0';
}

static inline void ffStrbufClear(FFstrbuf* strbuf) {
    if (strbuf->allocated > 0) {
        strbuf->chars[0] = '\0';
    }
    strbuf->length = 0;
}

bool ffStrbufRemoveSubstr(FFstrbuf* strbuf, uint32_t startIndex, uint32_t endIndex) {
    if (startIndex >= endIndex || startIndex >= strbuf->length) {
        return false;
    }
    if (endIndex > strbuf->length) {
        endIndex = strbuf->length;
    }
    if (strbuf->allocated > 0) {
        memmove(strbuf->chars + startIndex, strbuf->chars + endIndex, strbuf->length - endIndex);
    }
    strbuf->length -= (endIndex - startIndex);
    if (strbuf->allocated > 0) {
        strbuf->chars[strbuf->length] = '\0';
    }
    return true;
}

int main() {
    FFstrbuf strbuf;
    ffStrbufInitA(&strbuf, 16);

    klee_make_symbolic(strbuf.chars, 16, "strbuf_chars");
    strbuf.chars[15] = '\0';

    uint32_t len;
    klee_make_symbolic(&len, sizeof(len), "len");
    klee_assume(len < 16);
    strbuf.length = len;

    // Test ffStrbufEndsWithC
    char c;
    klee_make_symbolic(&c, sizeof(c), "c");

    bool ends = ffStrbufEndsWithC(&strbuf, c);

    if (len > 0) {
        // If it ends with c, the last char must be c
        if (ends) {
            klee_assert(strbuf.chars[len - 1] == c);
        } else {
            klee_assert(strbuf.chars[len - 1] != c);
        }
    } else {
        klee_assert(ends == false);
    }

    // Test ffStrbufRemoveSubstr
    uint32_t startIndex, endIndex;
    klee_make_symbolic(&startIndex, sizeof(startIndex), "startIndex");
    klee_make_symbolic(&endIndex, sizeof(endIndex), "endIndex");
    klee_assume(startIndex < 16);
    klee_assume(endIndex < 16);

    uint32_t oldLen = strbuf.length;
    bool modified = ffStrbufRemoveSubstr(&strbuf, startIndex, endIndex);

    if (startIndex >= endIndex || startIndex >= oldLen) {
        klee_assert(modified == false);
        klee_assert(strbuf.length == oldLen);
    } else {
        klee_assert(modified == true);
        uint32_t actualEnd = (endIndex > oldLen) ? oldLen : endIndex;
        klee_assert(strbuf.length == oldLen - (actualEnd - startIndex));
    }

    ffStrbufDestroy(&strbuf);
    return 0;
}
